#!/usr/bin/env bash
# Fixture for eval "hooks-status-uninstall": the git and Claude tiers are
# installed (by the plugin's own installer); no CI tier.
. "$(dirname "$0")/../lib.sh"
fx_init "$0"

fx_write src/index.js <<'JS'
console.log('hello');
JS
fx_write docs/architecture/system-overview.md <<'MD'
<!-- Generated by doc-superpowers -->

# Architecture

A one-file CLI (`src/index.js`).
MD
fx_commit "init"
printf 'docs/architecture/system-overview.md:src/index.js:architecture\n' | dt build-index >/dev/null
fx_commit "docs: index"
fx_install install --git --claude >/dev/null 2>&1 || fx_die "install --git --claude failed"

fx_expect "the git pre-commit hook is installed" grep -q "doc-superpowers hook v" .git/hooks/pre-commit
fx_expect "the Claude gate is installed" test -f .claude/hooks/doc-superpowers/pre-commit-gate.sh
fx_expect "the Claude settings carry the gate" grep -q "PreToolUse" .claude/settings.local.json
fx_expect "no CI tier" test ! -e .github/workflows
